            if (perfEl) perfEl.textContent = (ds.oeePerformance || 84).toFixed(1) + '%';
            if (qualEl) qualEl.textContent = (ds.quality || 93).toFixed(1) + '%';
            if (ehiEl) ehiEl.textContent = Math.round(ds.equipmentHealth || 50);
            if (oesEl) oesEl.textContent = Math.round(ds.oesScore || 30);
            if (alertsEl) alertsEl.textContent = ds.activeAlerts || 0;
        }

        _showRandomEvent(state) {
            var ds = state.domainState || {};
            var alertBox = document.getElementById('alertBox');
            var alertMsg = document.getElementById('alertMessage');
            if (!alertBox || !alertMsg) return;

            var seed = ds.randomSeed || 0;
            var events = [
                'evt_air',
                'evt_vibration',
                'evt_false_alarm',
                'evt_quality_notice',
                'evt_specialist',
                'evt_energy'
            ];
            var eventIdx = seed % events.length;
            alertBox.style.display = 'block';
            alertMsg.innerHTML = '<br>' + window.mySimulation.t(events[eventIdx]);

            var numAlerts = 1 + (seed % 3);
            if (ds.sensorCoverage > 60) numAlerts += 2;
            ds.activeAlerts = numAlerts;
        }

        _updateR3Availability(ds) {
            var twinEl = document.getElementById('chkDigitalTwin');
            if (twinEl) {
                var canTwin = ds.hasHistorian && ds.hasMLPlatform;
                twinEl.disabled = !canTwin;
                var prereqEl = document.getElementById('twinPrereq');
                if (prereqEl) {
                    prereqEl.style.color = canTwin ? '#27ae60' : '#e74c3c';
                    prereqEl.setAttribute('data-i18n', canTwin ? 'opt_twin_prereq_met' : 'opt_twin_prereq');
                    prereqEl.textContent = window.mySimulation.t(canTwin ? 'opt_twin_prereq_met' : 'opt_twin_prereq');
                }
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var s = parseInt(document.getElementById('sensorInput')?.value || 0);
                var e = parseInt(document.getElementById('edgeInput')?.value || 0);
                var a = parseInt(document.getElementById('analyticsInput')?.value || 0);
                var w = parseInt(document.getElementById('workforceInput')?.value || 0);
                var total = s + e + a + w;

                if (total > 2400000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_exceeded'), 'warning'
                    );
                    return false;
                }

                decisions.sensorBudget = s;
                decisions.edgeBudget = e;
                decisions.analyticsBudget = a;
                decisions.workforceBudget = w;
            }

            if (period === 2) {
                var maintEl = document.getElementById('maintenanceSelect');
                var prodEl = document.getElementById('productionSelect');
                var cyberEl = document.getElementById('cyberSelect');
                if (maintEl) decisions.maintenanceStrategy = maintEl.value;
                if (prodEl) decisions.productionRate = prodEl.value;
                if (cyberEl) decisions.cyberResponse = cyberEl.value;
            }

            if (period === 3) {
                var investments = [];
                var totalCost = 0;
                var checks = [
                    { id: 'chkDigitalTwin', key: 'digitalTwin', cost: 280000 },
                    { id: 'chkPredQuality', key: 'predQuality', cost: 160000 },
                    { id: 'chkEnergy', key: 'energyAnalytics', cost: 95000 },
                    { id: 'chkMobile', key: 'mobileApp', cost: 55000 },
                    { id: 'chkAutonomous', key: 'autonomousMaint', cost: 120000 },
                    { id: 'chkSupplyChain', key: 'supplyChain', cost: 140000 }
                ];
                checks.forEach(function(c) {
                    var el = document.getElementById(c.id);
                    if (el && el.checked && !el.disabled) {
                        investments.push(c.key);
                        totalCost += c.cost;
                    }
                });

                var ds = window.mySimulation.state.domainState;
                if (totalCost > ds.r3Budget) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('r3_budget_exceeded'), 'warning'
                    );
                    return false;
                }
                decisions.r3Investments = investments;
                decisions.r3TotalCost = totalCost;
            }

            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            var results = { period: period };

            if (period === 1) {
                results = this._calculateRound1(ds, d);
            } else if (period === 2) {
                results = this._calculateRound2(ds, d);
            } else if (period === 3) {
                results = this._calculateRound3(ds, d);
            }

            ds.oeeHistory.push(ds.oee);
            ds.cpuHistory.push(ds.costPerUnit);
            ds.downtimeHistory.push(ds.unplannedDowntimeMin);

            results.period = period;
            results.oee = ds.oee;
            results.costPerUnit = ds.costPerUnit;
            results.downtime = ds.unplannedDowntimeMin;
            results.dmi = ds.dmi;

            // Platform score: the finalScore composite of getPerformanceSummary (native 0-100) on the play so far.
            state.domainState.performance = Object.assign({}, (typeof state.domainState.performance === 'object' && state.domainState.performance) || {}, { overallScore: Math.max(0, Math.min(100, this._compositeScore(ds).finalScore)) });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: ds });
            }, 500);

            return results;
        }

        _calculateRound1(ds, d) {
            ds.sensorInvestment = d.sensorBudget;
            ds.edgeInvestment = d.edgeBudget;
            ds.analyticsInvestment = d.analyticsBudget;
            ds.workforceInvestment = d.workforceBudget;

            var totalSpent = d.sensorBudget + d.edgeBudget + d.analyticsBudget + d.workforceBudget;
            ds.budgetRemaining = 2400000 - totalSpent;

            ds.sensorCoverage = Math.round((d.sensorBudget / 1200000) * 100);

            ds.hasNetworkSegmentation = d.edgeBudget >= 400000;
            ds.hasHistorian = d.edgeBudget >= 250000;
            ds.hasCMMSIntegration = d.edgeBudget >= 350000;

            if (d.analyticsBudget >= 350000) {
                ds.analyticsLevel = 4;
                ds.hasMLPlatform = true;
            } else if (d.analyticsBudget >= 250000) {
                ds.analyticsLevel = 3;
                ds.hasMLPlatform = true;
            } else if (d.analyticsBudget >= 150000) {
                ds.analyticsLevel = 2;
                ds.hasMLPlatform = false;
            } else {
                ds.analyticsLevel = 1;
                ds.hasMLPlatform = false;
            }

            var baseOES = 30;
            if (d.workforceBudget >= 50000) baseOES += 5;
            if (d.workforceBudget >= 100000) baseOES += 12;
            if (d.workforceBudget >= 175000) baseOES += 15;
            if (d.workforceBudget >= 250000) baseOES += 18;
            if (d.workforceBudget >= 350000) baseOES += 20;
            ds.oesScore = Math.min(100, baseOES);
            ds.overrideReduction = d.workforceBudget >= 200000 ? 40 : (d.workforceBudget >= 100000 ? 20 : 0);

            var sensorAvailBoost = (ds.sensorCoverage / 100) * 8;
            ds.availability = 78 + sensorAvailBoost;
            var analyticsQualBoost = (ds.analyticsLevel - 1) * 1.5;
            ds.quality = 93 + analyticsQualBoost;
            ds.oeePerformance = 84;
            ds.oee = parseFloat(((ds.availability / 100) * (ds.oeePerformance / 100) * (ds.quality / 100) * 100).toFixed(1));

            ds.equipmentHealth = 50 + Math.round(ds.sensorCoverage * 0.35);
            ds.costPerUnit = 18.40;
            ds.totalUnitsProduced = 0;

            this._calculateDMI(ds);

            return {
                sensorCoverage: ds.sensorCoverage,
                hasSegmentation: ds.hasNetworkSegmentation,
                hasHistorian: ds.hasHistorian,
                analyticsLevel: ds.analyticsLevel,
                oesScore: ds.oesScore,
                oee: ds.oee,
                budgetSpent: totalSpent,
                dmi: ds.dmi
            };
        }

        _calculateRound2(ds, d) {
            var seed = ds.randomSeed || 0;
            var eventLog = '';
            var downtimeThisRound = 0;
            var maintCost = 0;
            var unitsProd = 0;

            var prodMultiplier = 1.0;
            var degradationMultiplier = 1.0;
            if (d.productionRate === 'full') {
                prodMultiplier = 1.0;
                degradationMultiplier = 1.3;
            } else if (d.productionRate === 'reduced') {
                prodMultiplier = 0.8;
                degradationMultiplier = 1.0;
            } else {
                prodMultiplier = 0;
                degradationMultiplier = 0;
            }

            var healthDrop = 15 * degradationMultiplier;
            if (ds.sensorCoverage < 40) healthDrop *= 1.4;
            ds.equipmentHealth = Math.max(0, ds.equipmentHealth - healthDrop);

            if (d.maintenanceStrategy === 'schedule_now') {
                var plannedDowntime = 120;
                maintCost = 35000;
                ds.equipmentHealth = Math.min(95, ds.equipmentHealth + 40);
                downtimeThisRound = 0;
                eventLog += '<br>' + window.mySimulation.t('log_maint_planned');
            } else if (d.maintenanceStrategy === 'defer') {
                var failChance = ds.sensorCoverage > 60 ? 0.2 : 0.45;
                var seedMod = (seed * 7 + 13) % 100;
                if (seedMod < failChance * 100) {
                    downtimeThisRound = 360 + (seed % 300);
                    maintCost = 50000 + (seed % 70000);
                    ds.equipmentHealth = Math.max(10, ds.equipmentHealth - 25);
                    eventLog += '<br>' + window.mySimulation.t('log_maint_defer_fail');
                } else {
                    downtimeThisRound = 0;
                    maintCost = 8000;
                    eventLog += '<br>' + window.mySimulation.t('log_maint_defer_ok');
                }
            } else {
                var emergFailChance = ds.sensorCoverage > 50 ? 0.55 : 0.80;
                var seedMod2 = (seed * 11 + 37) % 100;
                if (seedMod2 < emergFailChance * 100) {
                    downtimeThisRound = 480 + (seed % 600);
                    maintCost = 80000 + (seed % 40000);
                    ds.equipmentHealth = Math.max(5, ds.equipmentHealth - 35);
                    eventLog += '<br>' + window.mySimulation.t('log_maint_catastrophic');
                } else {
                    downtimeThisRound = 120;
                    maintCost = 25000;
                    eventLog += '<br>' + window.mySimulation.t('log_maint_minor');
                }
            }

            var responseDelay = ds.oesScore >= 70 ? 0 : (ds.oesScore >= 50 ? 1 : 2);
            downtimeThisRound += responseDelay * 60;

            var overrideRisk = Math.max(0, 30 - ds.overrideReduction);
            if ((seed * 3 + 7) % 100 < overrideRisk) {
                downtimeThisRound += 90;
                eventLog += '<br>' + window.mySimulation.t('log_override');
            }

            var cyberDowntime = 0;
            var cyberCost = 0;
            if (d.cyberResponse === 'isolate') {
                ds.oeePerformance = ds.oeePerformance * 0.85;
                cyberCost = 15000;
                eventLog += '<br>' + window.mySimulation.t('log_cyber_isolate');
            } else if (d.cyberResponse === 'investigate') {
                if (ds.hasNetworkSegmentation) {
                    cyberCost = 45000;
                    eventLog += '<br>' + window.mySimulation.t('log_cyber_mssp_ok');
                } else {
                    cyberDowntime = 240;
                    cyberCost = 95000;
                    eventLog += '<br>' + window.mySimulation.t('log_cyber_mssp_breach');
                }
            } else if (d.cyberResponse === 'patch') {
                if (ds.hasNetworkSegmentation) {
                    cyberCost = 25000;
                    eventLog += '<br>' + window.mySimulation.t('log_cyber_patch_ok');
                } else {
                    cyberDowntime = 480;
                    cyberCost = 180000;
                    ds.quality -= 2;
                    eventLog += '<br>' + window.mySimulation.t('log_cyber_ransomware');
                    ds.cyberDamage = 1;
                }
            } else {
                cyberDowntime = 720;
                cyberCost = 180000;
                ds.quality -= 3;
                ds.availability -= 8;
                eventLog += '<br>' + window.mySimulation.t('log_cyber_ignore');
                ds.cyberDamage = 2;
            }

            downtimeThisRound += cyberDowntime;
            maintCost += cyberCost;
            ds.unplannedDowntimeMin += downtimeThisRound;
            ds.totalMaintenanceCost += maintCost;

            var availableMinutes = 12 * 480;
            var productiveMinutes = Math.max(0, availableMinutes - downtimeThisRound - 120);
            ds.availability = Math.max(40, parseFloat(((productiveMinutes / availableMinutes) * 100).toFixed(1)));

            var sensorPerfBoost = (ds.sensorCoverage / 100) * 6;
            ds.oeePerformance = Math.max(50, parseFloat((84 + sensorPerfBoost) * prodMultiplier).toFixed(1));

            var analyticsQualBoost = (ds.analyticsLevel - 1) * 1.5;
            ds.quality = Math.max(70, parseFloat((93 + analyticsQualBoost - (ds.cyberDamage * 2)).toFixed(1)));

            ds.oee = parseFloat(((ds.availability / 100) * (ds.oeePerformance / 100) * (ds.quality / 100) * 100).toFixed(1));

            var baseUnits = 15000;
            unitsProd = Math.round(baseUnits * (ds.oee / 100) * prodMultiplier);
            ds.totalUnitsProduced += unitsProd;

            var totalCost = (unitsProd * 18.40) + maintCost + (downtimeThisRound * 53.33);
            ds.costPerUnit = unitsProd > 0 ? parseFloat((totalCost / unitsProd).toFixed(2)) : 999;

            ds.r3Budget = ds.oee >= 70 ? 400000 : 200000;

            this._calculateDMI(ds);

            ds.eventLog = eventLog;

            return {
                maintenanceStrategy: d.maintenanceStrategy,
                productionRate: d.productionRate,
                cyberResponse: d.cyberResponse,
                downtimeMinutes: downtimeThisRound,
                maintenanceCost: maintCost,
                unitsProduced: unitsProd,
                oee: ds.oee,
                costPerUnit: ds.costPerUnit,
                dmi: ds.dmi,
                eventSummary: eventLog
            };
        }

        _calculateRound3(ds, d) {
            var investments = d.r3Investments || [];
            var totalR3Cost = d.r3TotalCost || 0;
            ds.r3Spent = totalR3Cost;
            var eventLog = '';
            var oeeBoost = 0;
            var qualityBoost = 0;
            var availBoost = 0;
            var mttrReduction = 0;
            var energySaving = 0;
            var downtimeThisRound = 0;

            investments.forEach(function(inv) {
                if (inv === 'digitalTwin') {
                    ds.hasDigitalTwin = true;
                    oeeBoost += 8;
                    eventLog += '<br>' + window.mySimulation.t('log_twin');
                }
                if (inv === 'predQuality') {
                    ds.hasPredQuality = true;
                    qualityBoost += 3;
                    eventLog += '<br>' + window.mySimulation.t('log_predq');
                }
                if (inv === 'energyAnalytics') {
                    ds.hasEnergyAnalytics = true;
                    energySaving = 0.10;
                    eventLog += '<br>' + window.mySimulation.t('log_energy');
                }
                if (inv === 'mobileApp') {
                    ds.hasMobileApp = true;
                    mttrReduction = 0.20;
                    availBoost += 2;
                    eventLog += '<br>' + window.mySimulation.t('log_mobile');
                }
                if (inv === 'autonomousMaint') {
                    ds.hasAutonomousMaint = true;
                    availBoost += 3;
                    eventLog += '<br>' + window.mySimulation.t('log_autonomous');
                }
                if (inv === 'supplyChain') {
                    ds.hasSupplyChain = true;
                    eventLog += '<br>' + window.mySimulation.t('log_supply');
                }
            });

            ds.availability = Math.min(98, ds.availability + availBoost);
            ds.quality = Math.min(99, ds.quality + qualityBoost);
            var totalOEEBefore = ds.oee;
            ds.oee = parseFloat(((ds.availability / 100) * (ds.oeePerformance / 100) * (ds.quality / 100) * 100).toFixed(1));
            ds.oee = Math.min(88, ds.oee + oeeBoost);

            var seed = ds.randomSeed || 0;
            var r3FailChance = ds.sensorCoverage > 60 ? 0.15 : 0.35;
            if ((seed * 17 + 43) % 100 < r3FailChance * 100) {
                if (ds.hasSupplyChain) {
                    downtimeThisRound = 60;
                    ds.totalMaintenanceCost += 15000;
                    eventLog += '<br>' + window.mySimulation.t('log_minor_issue');
                } else {
                    downtimeThisRound = 180;
                    ds.totalMaintenanceCost += 40000;
                    eventLog += '<br>' + window.mySimulation.t('log_failure');
                }
            }

            ds.unplannedDowntimeMin += downtimeThisRound;

            var baseUnits = 15000;
            var prodFactor = ds.oee / 100;
            var unitsProd = Math.round(baseUnits * prodFactor);
            ds.totalUnitsProduced += unitsProd;

            var energyCostFactor = 1.0 - energySaving;
            var emergencyCostFactor = ds.hasSupplyChain ? 0.7 : 1.0;
            var totalCost = (unitsProd * 18.40 * energyCostFactor) + (ds.totalMaintenanceCost * 0.3 * emergencyCostFactor) + (downtimeThisRound * 53.33);
            ds.costPerUnit = unitsProd > 0 ? parseFloat((totalCost / unitsProd).toFixed(2)) : 999;

            this._calculateDMI(ds);

            ds.eventLog = eventLog;

            return {
                investments: investments,
                r3Cost: totalR3Cost,
                oeeImprovement: parseFloat((ds.oee - totalOEEBefore).toFixed(1)),
                downtimeMinutes: downtimeThisRound,
                unitsProduced: unitsProd,
                oee: ds.oee,
                costPerUnit: ds.costPerUnit,
                dmi: ds.dmi,
                eventSummary: eventLog
            };
        }

        _calculateDMI(ds) {
            var dmi = 0;
            if (ds.sensorCoverage >= 75) dmi += 20;
            else if (ds.sensorCoverage >= 50) dmi += 10;

            if (ds.edgeInvestment >= 285000) dmi += 15;
            else if (ds.edgeInvestment >= 150000) dmi += 7;

            if (ds.hasNetworkSegmentation) dmi += 15;

            if (ds.hasHistorian && ds.analyticsLevel >= 3) dmi += 15;
            else if (ds.hasHistorian || ds.analyticsLevel >= 2) dmi += 7;

            if (ds.hasCMMSIntegration) dmi += 10;

            if (ds.hasDigitalTwin) dmi += 15;

            if (ds.oesScore >= 70) dmi += 10;
            else if (ds.oesScore >= 50) dmi += 5;

            ds.dmi = Math.min(100, dmi);
        }

