            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('oeeDisplay', 'domainState.oee', function(v) { return (v || 0).toFixed(1) + '%'; });
            uiManager.bind('budgetDisplay', 'domainState.budgetRemaining', function(v) { return '€' + Math.round(v || 0).toLocaleString(); });
            uiManager.bind('downtimeDisplay', 'domainState.unplannedDowntimeMin', function(v) { return Math.round(v || 0) + ' min'; });
            uiManager.bind('dmiDisplay', 'domainState.dmi', function(v) { return Math.round(v || 0) + '/100'; });
            if (!this._langWired) {
                this._langWired = true;
                var self = this;
                document.addEventListener('express:langchanged', function() {
                    try { self._updateBriefing(window.mySimulation.state); } catch (e) {}
                });
            }
        }

