                { key: 'results.oee', label: 'OEE (%)', i18nKey: 'col_oee', formatter: function(v) { return (v || 0).toFixed(1) + '%'; } },
                { key: 'results.costPerUnit', label: 'Cost/Unit (€)', i18nKey: 'col_cpu', formatter: function(v) { return '€' + (v || 0).toFixed(2); } },
                { key: 'results.downtime', label: 'Downtime (min)', i18nKey: 'col_downtime', formatter: function(v) { return Math.round(v || 0) + ' min'; } },
                { key: 'results.dmi', label: 'DMI', i18nKey: 'col_dmi', formatter: function(v) { return Math.round(v || 0) + '/100'; } }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;

            if (period === 1) {
                if (ds.sensorCoverage < 50) return window.mySimulation.t('hint_low_sensors');
                if (!ds.hasNetworkSegmentation) return window.mySimulation.t('hint_no_segmentation');
                if (ds.oesScore < 50) return window.mySimulation.t('hint_low_oes');
            }
            if (period === 2) {
                if (ds.cyberDamage > 0) return window.mySimulation.t('hint_cyber_damage');
                if (ds.unplannedDowntimeMin > 400) return window.mySimulation.t('hint_high_downtime');
                if (ds.oee >= 75) return window.mySimulation.t('hint_good_oee');
            }
            if (period === 3) {
                if (ds.dmi >= 80) return window.mySimulation.t('hint_high_dmi');
                if (ds.oee >= 80) return window.mySimulation.t('hint_excellent_oee');
            }
            return null;
        }

        // Composite of the final verdict, read from domainState so calculateResults can report it every round.
        _compositeScore(ds) {
            var oeeValues = (ds.oeeHistory || []);
            var avgOEE = oeeValues.length > 0 ? oeeValues.reduce(function(s, v) { return s + v; }, 0) / oeeValues.length : 0;
            var finalCPU = ds.costPerUnit || 0;
            var totalDowntime = ds.unplannedDowntimeMin || 0;
            var finalDMI = ds.dmi || 0;

            var oeeScore = Math.min(100, (avgOEE / 88) * 100);
            var cpuScore = finalCPU > 0 ? Math.min(100, (18.40 / finalCPU) * 100) : 0;
            var downtimeScore = Math.max(0, 100 - (totalDowntime / 12));
            var dmiScore = finalDMI;

            var finalScore = Math.round(oeeScore * 0.35 + cpuScore * 0.25 + downtimeScore * 0.20 + dmiScore * 0.20);
            return { avgOEE: avgOEE, finalCPU: finalCPU, totalDowntime: totalDowntime, finalDMI: finalDMI, finalScore: finalScore };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation?.state?.domainState || {};

            var cs = this._compositeScore(ds);
            var avgOEE = cs.avgOEE;
            var finalCPU = cs.finalCPU;
            var totalDowntime = cs.totalDowntime;
            var finalDMI = cs.finalDMI;
            var finalScore = cs.finalScore;

            var performance = window.mySimulation.t('perf_needs');
            if (finalScore >= 80) performance = window.mySimulation.t('perf_world_class');
            else if (finalScore >= 65) performance = window.mySimulation.t('perf_strong');
            else if (finalScore >= 50) performance = window.mySimulation.t('perf_competent');

            var insights = [];
            if (avgOEE >= 78) insights.push(window.mySimulation.t('insight_oee_excellent'));
            if (avgOEE < 65) insights.push(window.mySimulation.t('insight_oee_low'));
            if (ds.hasNetworkSegmentation) insights.push(window.mySimulation.t('insight_segmentation'));
            if (!ds.hasNetworkSegmentation && ds.cyberDamage > 0) insights.push(window.mySimulation.t('insight_ransomware'));
            if (ds.oesScore >= 70) insights.push(window.mySimulation.t('insight_oes_high'));
            if (ds.oesScore < 50) insights.push(window.mySimulation.t('insight_oes_low'));
            if (ds.hasDigitalTwin) insights.push(window.mySimulation.t('insight_twin'));
            if (finalDMI >= 80) insights.push(window.mySimulation.t('insight_dmi'));

            return {
                finalScore: finalScore,
                avgOEE: parseFloat(avgOEE.toFixed(1)),
                finalCPU: finalCPU,
                totalDowntime: totalDowntime,
                finalDMI: finalDMI,
                performance: performance,
                insights: insights
            };
        }

